import { defineConfig } from "orval";

const input = { target: "../api/openapi.yaml" };

// The header of every generated file leaves out the spec's version and description: release-please bumps info.version
// on every release, which would otherwise change every file here without a regeneration in the release pull request.
const header = () => ["Generated by orval from api/openapi.yaml.", "Do not edit manually."];

// Two outputs, each in a directory of its own because clean empties the directories it writes to. The output is
// written raw, without a formatter, so that the same spec always gives the same files. Every request of the client
// goes through apiFetch in src/lib/api.ts, which adds the CSRF token and turns problems into errors.
export default defineConfig({
  client: {
    input,
    output: {
      mode: "tags-split",
      target: "src/api/gen/endpoints/muster.ts",
      schemas: "src/api/gen/model",
      client: "react-query",
      httpClient: "fetch",
      baseUrl: "/api/v1",
      mock: true,
      clean: true,
      override: {
        header,
        mutator: { path: "src/lib/api.ts", name: "apiFetch" },
        fetch: { includeHttpResponseReturnType: false },
      },
    },
  },
  zod: {
    input,
    output: {
      mode: "tags-split",
      target: "src/api/gen/zod/muster.ts",
      client: "zod",
      fileExtension: ".zod.ts",
      clean: true,
      override: { header },
    },
  },
});
